CREATE TABLE ReceivablePayments(id INTEGER PRIMARY KEY,receivable_id INTEGER NOT NULL REFERENCES Receivables(id),sale_id INTEGER NOT NULL REFERENCES Sales(id),customer_id INTEGER NOT NULL REFERENCES Customers(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),method TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,collected_at TEXT NOT NULL,created_by INTEGER REFERENCES Users(id),created_at TEXT NOT NULL);
CREATE INDEX idx_receivable_payments_account ON ReceivablePayments(receivable_id,collected_at,id);
CREATE TABLE SaleReturns(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES Sales(id),customer_id INTEGER REFERENCES Customers(id),idempotency_key TEXT NOT NULL UNIQUE,returned_at TEXT NOT NULL,total_minor INTEGER NOT NULL CHECK(total_minor>=0),receivable_credit_minor INTEGER NOT NULL DEFAULT 0 CHECK(receivable_credit_minor>=0),refund_minor INTEGER NOT NULL DEFAULT 0 CHECK(refund_minor>=0),refund_method TEXT,reason TEXT NOT NULL,created_by INTEGER REFERENCES Users(id),created_at TEXT NOT NULL);
CREATE TABLE SaleReturnItems(id INTEGER PRIMARY KEY,sale_return_id INTEGER NOT NULL REFERENCES SaleReturns(id),sale_item_id INTEGER NOT NULL REFERENCES SaleItems(id),product_id INTEGER NOT NULL REFERENCES Products(id),base_quantity NUMERIC NOT NULL CHECK(base_quantity>0),refund_minor INTEGER NOT NULL CHECK(refund_minor>=0),cogs_minor INTEGER NOT NULL CHECK(cogs_minor>=0));
CREATE TABLE SaleReturnAllocations(id INTEGER PRIMARY KEY,sale_return_item_id INTEGER NOT NULL REFERENCES SaleReturnItems(id),sale_item_allocation_id INTEGER NOT NULL REFERENCES SaleItemAllocations(id),batch_id INTEGER NOT NULL REFERENCES ProductBatches(id),base_quantity NUMERIC NOT NULL CHECK(base_quantity>0));
CREATE INDEX idx_sale_returns_sale ON SaleReturns(sale_id,returned_at,id);
CREATE INDEX idx_sale_return_items_source ON SaleReturnItems(sale_item_id);
